(()=>{
 const q=s=>document.querySelector(s),status=q('#recovery-status');
 const params=new URLSearchParams(location.hash.slice(1)),purpose=params.has('verify')?'verify':params.has('reset')?'reset':null,token=params.get(purpose)||'';
 if(purpose){history.replaceState(null,'',location.pathname);q('#request-form').hidden=true;q('#recovery-title').textContent=purpose==='verify'?'Подтверждение почты':'Новый пароль';q(purpose==='verify'?'#verify-form':'#reset-form').hidden=false;}
 async function api(path,data){const response=await fetch('/api/auth/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},body:JSON.stringify(data),cache:'no-store'});const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Проверьте поля и попробуйте снова.');return result;}
 q('#show-password').onchange=event=>q('#reset-form').querySelectorAll('input[name]').forEach(input=>input.type=event.target.checked?'text':'password');
 q('#request-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;status.textContent='Отправляем запрос…';try{const result=await api('forgot-password',{email:form.elements.email.value.trim()});status.textContent=result.message}catch(error){status.textContent=error.message}finally{setTimeout(()=>button.disabled=false,60000)}};
 for(const [id,path] of [['#reset-form','reset-password'],['#verify-form','verify-email/confirm']])q(id).onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');if(id==='#reset-form'&&form.elements.password.value!==form.elements.repeat.value){status.textContent='Пароли не совпадают.';return}button.disabled=true;status.textContent='Сохраняем…';try{const result=await api(path,{token,...(id==='#reset-form'?{new_password:form.elements.password.value}:{})});form.reset();form.hidden=true;status.textContent=result.message}catch(error){status.textContent=error.message;q('#new-link').hidden=false}finally{button.disabled=false}};
})();
